import"./chunk-ZW5NV4UO.js";var a={lv:{title:"M\u0101ksla un kult\u016Bra Mastodon: kam sekot latviski",description:"Gr\u0101matas, kino, m\u016Bzika un vizu\u0101l\u0101 m\u0101ksla latviski: septi\u0146u Mastodon profilu izlase ar publisku pl\u016Bsmas priek\u0161skat\u012Bjumu.",heading:"M\u0101ksla un kult\u016Bra Mastodon",listTitle:"M\u0101ksla un kult\u016Bra",intro:["Ko las\u012Bt, skat\u012Bties un klaus\u012Bties? \u0160aj\u0101 nelielaj\u0101 izlas\u0113 ir septi\u0146i profili, kuru autori latviski dal\u0101s ar gr\u0101matu, kino, m\u016Bzikas un vizu\u0101l\u0101s m\u0101kslas pieredzi. L\u012Bdz\u0101s ieteikumiem ir ar\u012B pa\u0161u rado\u0161ais darbs un ikdienas ieraksti.","Atver priek\u0161skat\u012Bjumu, iepaz\u012Bsti autorus un izv\u0113lies, kam sekot. #Kino un #Kult\u016Bra var pal\u012Bdz\u0113t atrast v\u0113l citas balsis. #Gr\u0101matas pa\u0161laik ir kluss t\u0113mturis; negaidi past\u0101v\u012Bgu jaunu ierakstu pl\u016Bsmu. Kop\u012Bgajos t\u0113mturos var b\u016Bt ar\u012B citas valodas un blakust\u0113mas."],faq:[{q:"Vai vajadz\u012Bgs konts?",a:"Lai iepaz\u012Btos ar profiliem un las\u012Btu publisko priek\u0161skat\u012Bjumu, konts nav vajadz\u012Bgs. Ar Mastodon kontu vari sekot izv\u0113l\u0113tajiem autoriem un t\u0113mturiem vai izveidot atsevi\u0161\u0137u sarakstu."},{q:"Vai \u0161\u012B ir tikai profesion\u0101lu m\u0101kslinieku izlase?",a:"N\u0113. Te ir gan rado\u0161\u0101 darba veidot\u0101ji, gan las\u012Bt\u0101ji un skat\u012Bt\u0101ji, kuri dal\u0101s sav\u0101 pieredz\u0113. Autori raksta ar\u012B par cit\u0101m t\u0113m\u0101m un da\u017Ek\u0101rt cit\u0101s valod\u0101s."},{q:"K\u0101 pieteikt profilu vai iz\u0146emt savu?",a:"Raksti @mawkingbird@mastodon.social. V\u0113rt\u0113jam pa\u0161u autoru ierakstus, valodu, neseno aktivit\u0101ti un profila atra\u0161anas at\u013Caujas. Savu profilu vari l\u016Bgt iz\u0146emt."}]}};export{a as COPY};
